item.command:
/bin/bash -lc "python - <<'PY'
import zipfile
for z in ['inputs/scogs_animals.zip','inputs/scogs_fungi.zip']:
    with zipfile.ZipFile(z) as f: names=set(f.namelist())
    alns={x for x in names if x.endswith('.clipkit')}
    trees={x.removesuffix('.treefile') for x in names if x.endswith('.clipkit.treefile')}
    miss=sorted(alns-trees)
    print(z, len(alns), len(trees), len(miss), miss[:10])
PY
unzip -p inputs/scogs_animals.zip 1001384at2759.faa.mafft.clipkit.log | tail -n 35 || true"

