p='run_trace/galaxy_tool_schema_005/tool_response.json'
d=json.load(open(p))
# locate operation conditional recursively

def walk(x,path=''):
    if isinstance(x,dict):
        if x.get('name') in ('operation','input_mode','archives'):
            print(path, json.dumps(x,indent=2)[:12000])
        for k,v in x.items(): walk(v,path+'/'+str(k))
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,path+'/'+str(i))
walk(d)
PY"

